INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('a-station-in-daily-life','articles','published','https://www.tchac.taichung.gov.tw/building?pid=22&uid=33','2026-09-10',56,'{"slug":"a-station-in-daily-life","category":"鐵道文史","title":"木造車站旁，生活繼續往返","summary":"從月台上的牛眼窗，看見海線車站留下的日常尺度。","image":"/images/rinan-station-front.jpg","imageAlt":"日南車站木造站房正面","readingMinutes":2,"sourceLabel":"臺中市文化資產處｜日南車站","sourceUrl":"https://www.tchac.taichung.gov.tw/building?pid=22&uid=33","sections":[{"heading":"先看看這座車站","text":"日南車站位於臺中大甲，是海線留存的木造站房。從月台一側抬頭，可以看見高處的牛眼窗。木構、屋簷與月台，讓出發與回來都有一個熟悉的背景。"},{"heading":"留下來的建築，也在今天被使用","text":"日南車站於 2002 年 11 月 26 日公告為市定古蹟。文資資料保存建築的歷史；每一次進站、候車與接人，則讓這個地方繼續和生活相連。"},{"heading":"走出車站，再往日南裡走","text":"日南稻站就在車站旁。我們從這裡整理地方的故事，也邀請你把停留的時間拉長一點：看看展、認識周邊，再走進聚落。"}]}');
INSERT INTO content_records (id,kind,status,source,updated_at,sort_order,payload) VALUES ('a-place-to-stop','articles','published','使用者2026-09-17確認守橋營房背景；日南稻站設計需求文件之守橋兵營描述；編輯整理','2026-09-17',57,'{"slug":"a-place-to-stop","category":"空間日常","title":"車站旁，留一個可以坐一下的地方","summary":"關於稻站想成為的空間，和從這裡開始的相遇。","image":"","imageAlt":"","readingMinutes":2,"sourceLabel":"日南稻站｜空間與願景","sourceUrl":"","sections":[{"heading":"把空間重新打開","text":"日南稻站所在的舊空間，曾是守護鐵路橋梁的營房，也是一般人無法自由進入的軍方禁區。如今，我們以最小介入、可逆式改善整理營房，把曾經封閉的門慢慢打開。希望這裡可以看展、坐一下、聊聊天，也讓剛下火車的人有機會多認識日南。"},{"heading":"生活有很多種走法","text":"離鄉、返鄉、留下，或第一次抵達。田野、工廠、聚落與車站之間，交會著不同的生活。稻站想把這些經驗慢慢整理起來，透過策展與交流，讓彼此有機會遇見。"},{"heading":"從這裡，再往地方走","text":"空間規劃包含文化策展、風土米食、青年交流，以及旅遊與單車驛站。日常服務與開放時間將隨準備進度公告；可以先從展覽與走傱日南的活動認識我們。"}]}');
